package za.co.loopmanager;
import android.content.Context;import android.os.SystemClock;import android.provider.Settings;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={30,35})
public class SupportAccessTest {
 @Test public void contactLeaseExpiresAndCannotCarryAcrossReboots(){Context c=RuntimeEnvironment.getApplication();Settings.Global.putInt(c.getContentResolver(),Settings.Global.BOOT_COUNT,1);long now=SystemClock.elapsedRealtime();c.getSharedPreferences("loop.support",0).edit().putLong("boot",1).putLong("started",now).putLong("until",now+180000).putString("package","com.whatsapp").putBoolean("call",false).apply();assertTrue(SupportAccess.active(c));assertEquals(java.util.Collections.singletonList("com.whatsapp"),SupportAccess.packages(c));assertFalse(SupportAccess.callsAllowed(c));SystemClock.sleep(180001);assertFalse(SupportAccess.active(c));assertTrue(SupportAccess.packages(c).isEmpty());Settings.Global.putInt(c.getContentResolver(),Settings.Global.BOOT_COUNT,2);assertFalse(SupportAccess.active(c));}
 @Test public void arbitraryPackagesAndRewoundElapsedTimeAreNotGrantedAccess(){Context c=RuntimeEnvironment.getApplication();Settings.Global.putInt(c.getContentResolver(),Settings.Global.BOOT_COUNT,1);long now=SystemClock.elapsedRealtime();var p=c.getSharedPreferences("loop.support",0);p.edit().putLong("boot",1).putLong("started",now).putLong("until",now+180000).putString("package","com.example.unapproved").apply();assertTrue(SupportAccess.active(c));assertTrue(SupportAccess.packages(c).isEmpty());p.edit().putLong("started",now+1000).apply();assertFalse(SupportAccess.active(c));SupportAccess.end(c);assertFalse(SupportAccess.active(c));assertEquals("+27637246209",SupportAccess.PHONE);}
}
